(() => {
  function groups(cards){const m=new Map();cards.forEach(c=>{if(!m.has(c.value))m.set(c.value,[]);m.get(c.value).push(c)});return [...m.entries()].sort((a,b)=>a[0]-b[0])}
  function classify(cards){
    if(!cards||!cards.length)return null;const n=cards.length,g=groups(cards),counts=g.map(x=>x[1].length).sort((a,b)=>b-a),vals=g.map(x=>x[0]);
    if(n===2&&vals.includes(16)&&vals.includes(17))return {type:'rocket',main:17,n};
    if(g.length===1){if(n===1)return{type:'single',main:vals[0],n};if(n===2)return{type:'pair',main:vals[0],n};if(n===3)return{type:'triple',main:vals[0],n};if(n===4)return{type:'bomb',main:vals[0],n}}
    if(n===4&&counts[0]===3)return{type:'triple1',main:g.find(x=>x[1].length===3)[0],n};
    if(n===5&&counts[0]===3&&counts[1]===2)return{type:'triple2',main:g.find(x=>x[1].length===3)[0],n};
    const consecutive=vals.every((v,i)=>v<15&&(i===0||v===vals[i-1]+1));
    if(n>=5&&g.length===n&&consecutive)return{type:'straight',main:vals.at(-1),n};
    if(n>=6&&n%2===0&&g.length===n/2&&g.every(x=>x[1].length===2)&&consecutive)return{type:'pairs',main:vals.at(-1),n};
    if(n>=6&&n%3===0&&g.length===n/3&&g.every(x=>x[1].length===3)&&consecutive)return{type:'plane',main:vals.at(-1),n};
    if(n===6&&counts[0]===4)return{type:'four2',main:g.find(x=>x[1].length===4)[0],n};
    if(n===8&&counts[0]===4&&counts.slice(1).every(x=>x===2))return{type:'four2pairs',main:g.find(x=>x[1].length===4)[0],n};
    return null;
  }
  function beats(a,b){if(!a)return false;if(!b)return true;if(a.type==='rocket')return b.type!=='rocket';if(b.type==='rocket')return false;if(a.type==='bomb'&&b.type!=='bomb')return true;if(a.type!==b.type||a.n!==b.n)return false;return a.main>b.main}
  function seqCandidates(hand,size,each){const g=groups(hand).filter(x=>x[0]<15&&x[1].length>=each),out=[];for(let i=0;i<=g.length-size;i++){const run=g.slice(i,i+size);if(run.every((x,j)=>j===0||x[0]===run[j-1][0]+1))out.push(run.flatMap(x=>x[1].slice(0,each)))}return out}
  function candidates(hand,target){
    const g=groups(hand),out=[];g.forEach(x=>{for(let k=1;k<=Math.min(4,x[1].length);k++){const c=x[1].slice(0,k);if(classify(c))out.push(c)}});
    const sj=hand.find(c=>c.value===16),bj=hand.find(c=>c.value===17);if(sj&&bj)out.push([sj,bj]);
    if(target){if(target.type==='straight')out.push(...seqCandidates(hand,target.n,1));if(target.type==='pairs')out.push(...seqCandidates(hand,target.n/2,2));if(target.type==='plane')out.push(...seqCandidates(hand,target.n/3,3));}
    g.filter(x=>x[1].length>=3).forEach(t=>{const rest=hand.filter(c=>c.value!==t[0]);rest.forEach(c=>out.push([...t[1].slice(0,3),c]));groups(rest).filter(x=>x[1].length>=2).forEach(p=>out.push([...t[1].slice(0,3),...p[1].slice(0,2)]))});
    return out.filter((c,i)=>{const k=c.map(x=>x.id).sort().join();return out.findIndex(z=>z.map(x=>x.id).sort().join()===k)===i}).filter(c=>beats(classify(c),target)).sort((a,b)=>{const ca=classify(a),cb=classify(b);return (ca.type==='bomb')-(cb.type==='bomb')||ca.main-cb.main||a.length-b.length});
  }
  globalThis.CardRules = {classify, beats, groups, candidates, seqCandidates};
})();

(() => {
  const {classify, groups, candidates, seqCandidates} = CardRules;
  const power = kind => ['bomb', 'rocket'].includes(kind.type);
  function options(hand, target) {
    const plays = candidates(hand, target);
    if (!target) {
      for (const [minimum, copies] of [[5, 1], [3, 2], [2, 3]]) {
        for (let size = minimum; size <= 12; size++) {
          plays.push(...seqCandidates(hand, size, copies));
        }
      }
    }
    return plays;
  }
  function remove(hand, play) {
    const ids = new Set(play.map(card => card.id));
    return hand.filter(card => !ids.has(card.id));
  }
  function estimatedTurns(hand) {
    if (!hand.length) return 0;
    if (classify(hand)) return 1;
    const sequences = [seqCandidates(hand, 5, 1), seqCandidates(hand, 3, 2)];
    const grouped = groups(hand);
    const basic = grouped.length - Math.min(
      grouped.filter(([, cards]) => cards.length === 3).length,
      grouped.filter(([, cards]) => cards.length < 3).length
    );
    return Math.min(basic, ...sequences.flat().map(play => 1 + groups(remove(hand, play)).length));
  }
  function choose(hand, target, difficulty, remaining, unseen) {
    const plays = difficulty === 'easy' ? candidates(hand, target) : options(hand, target);
    if (difficulty === 'easy') {
      return (target ? plays[0] : plays.find(play => !power(classify(play)))) || null;
    }
    const whole = classify(hand);
    if (CardRules.beats(whole, target)) return hand;
    const counts = new Map(groups(hand).map(([rank, cards]) => [rank, cards.length]));
    const runs = seqCandidates(hand, 5, 1).map(play => new Set(play.map(card => card.value)));
    let best = null;
    let bestScore = Infinity;
    for (const play of plays) {
      const kind = classify(play);
      const rest = remove(hand, play);
      const used = groups(play);
      const splits = used.reduce((sum, [rank, cards]) => {
        const n = counts.get(rank);
        return sum + (n === cards.length ? 0 : n === 4 ? 9 : 2);
      }, 0);
      const brokenRun = kind.type === 'single' && counts.get(kind.main) === 1
        && runs.some(run => run.has(kind.main));
      let score = splits + (brokenRun ? 3 : 0) + kind.main / 12 - play.length * 1.1;
      if (power(kind) && remaining > 2 && rest.length > 4) score += 12;
      if (remaining <= 2) score -= kind.type === 'single' ? kind.main : play.length * 2;
      if (difficulty === 'hard') {
        score += estimatedTurns(rest) * 3;
        if (!target && !candidates(unseen, kind).length) score -= 3;
        if (classify(rest)) score -= 5;
      }
      if (score < bestScore) {
        best = play;
        bestScore = score;
      }
    }
    if (target && remaining > 2 && best && power(classify(best)) && hand.length > 7) return null;
    return best;
  }
  globalThis.CardStrategy = {choose};
})();

/* Shared rules: dual mode deliberately retains the original classifier. */
(() => {
  const modes = {duel:{n:2,decks:1,base:25,bottom:4},trio:{n:3,decks:1,base:17,bottom:3},four:{n:4,decks:2,base:25,bottom:8},teams:{n:4,decks:2,base:27,bottom:0}};
  function classify(cards, mode='duel') {
    if(mode==='duel') return CardRules.classify(cards);
    if(!cards?.length)return null;
    const n=cards.length,g=CardRules.groups(cards),multi=modes[mode].decks===2;
    if(multi && n===4 && g.length===2 && g.every(([v,c])=>v>=16&&c.length===2))return {type:'rocket',main:17,n};
    if(multi && g.length===1 && n>=4 && g[0][0]<16)return {type:'bomb',main:g[0][0],n};
    const base=CardRules.classify(cards);
    if(base && !(multi && ['rocket','triple1','four2','four2pairs'].includes(base.type)))return base;
    for(const each of (multi?[5]:[4,5])){
      const size=n/each;
      if(!Number.isInteger(size)||size<2)continue;
      for(let low=3;low+size-1<=14;low++){
        const core=g.filter(([v])=>v>=low&&v<low+size);
        if(core.length!==size||core.some(([,c])=>c.length!==3))continue;
        const wings=g.filter(([v])=>v<low||v>=low+size);
        if(each===4 && wings.reduce((s,[,c])=>s+c.length,0)===size && wings.every(([,c])=>c.length<=2) && !wings.some(([v])=>v===16)&&!wings.some(([v])=>v===17))return {type:'plane1',main:low+size-1,n};
        if(each===5 && wings.length===size && wings.every(([,c])=>c.length===2))return {type:'plane2',main:low+size-1,n};
      }
    }
    return null;
  }
  function beats(a,b){if(!a)return false;if(!b)return true;if(a.type==='rocket')return b.type!=='rocket';if(b.type==='rocket')return false;if(a.type==='bomb'){if(b.type!=='bomb')return true;return a.n!==b.n?a.n>b.n:a.main>b.main}return a.type===b.type&&a.n===b.n&&a.main>b.main}
  function options(hand,target,mode){
    if(mode==='duel')return CardRules.candidates(hand,target);
    const out=CardRules.candidates(hand,null),g=CardRules.groups(hand);
    for(const [minimum,each] of [[5,1],[3,2],[2,3]])for(let size=minimum;size<=12;size++)out.push(...CardRules.seqCandidates(hand,size,each));
    for(let size=2;size<=Math.floor(hand.length/4);size++)for(const core of CardRules.seqCandidates(hand,size,3)){
      const ranks=new Set(core.map(c=>c.value)),rest=g.filter(([v])=>!ranks.has(v));
      const singles=rest.filter(([v])=>v<16).flatMap(([,c])=>c.slice(0,2));
      if(singles.length>=size)out.push([...core,...singles.slice(0,size)]);
      const pairs=rest.filter(([,c])=>c.length>=2).slice(0,size);
      if(pairs.length===size)out.push([...core,...pairs.flatMap(([,c])=>c.slice(0,2))]);
    }
    for(const [v,c] of g)if(v<16)for(let size=4;size<=c.length;size++)out.push(c.slice(0,size));
    const kings=hand.filter(c=>c.value>=16);if(kings.length===4)out.push(kings);
    for(const [v,c] of g.filter(([,c])=>c.length>=4)){
      const rest=g.filter(([r])=>r!==v),singles=rest.flatMap(([,c])=>c);
      if(singles.length>=2)out.push([...c.slice(0,4),...singles.slice(0,2)]);
      const pairs=rest.filter(([,c])=>c.length>=2).slice(0,2);if(pairs.length===2)out.push([...c.slice(0,4),...pairs.flatMap(([,c])=>c.slice(0,2))]);
    }
    const seen=new Set();return out.filter(c=>{const key=c.map(x=>x.id).sort().join(',');if(seen.has(key))return false;seen.add(key);return beats(classify(c,mode),target)});
  }
  function deck(mode){const out=[];for(let copy=0;copy<modes[mode].decks;copy++)for(let v=3;v<=17;v++)for(const s of (v<16?['S','H','C','D']:[''])){const rank=v<11?''+v:({11:'J',12:'Q',13:'K',14:'A',15:'2',16:'SJ',17:'BJ'})[v],code=rank+s;out.push({id:code+(copy?'~'+copy:''),code,value:v})}return out}
  const rand=n=>{const limit=Math.floor(2**32/n)*n;let x;do{x=crypto.getRandomValues(new Uint32Array(1))[0]}while(x>=limit);return x%n};
  function deal(mode){const spec=modes[mode],d=deck(mode);for(let i=d.length-1;i;i--){const j=rand(i+1);[d[i],d[j]]=[d[j],d[i]]}const landlord=rand(spec.n),hands=Array.from({length:spec.n},(_,i)=>d.slice(i*spec.base,(i+1)*spec.base));const bottom=d.slice(spec.n*spec.base);hands[landlord].push(...bottom);return {mode,hands,bottom:bottom.map(c=>c.id),landlord,turn:landlord,lead:null,lastActor:null,passes:0,plays:Array.from({length:spec.n},()=>[]),ready:Array(spec.n).fill(false),winner:null,winners:[],last:null,played:[]}}
  function team(g,seat){return g.mode==='teams'?seat%2:seat===g.landlord?'landlord':'farmer'}
  function move(g,seat,action,ids){
    if(g.winner!==null)return '本局已结束';
    if(action==='ready'){g.ready[seat]=true;return}
    if(!g.ready.every(Boolean)||g.turn!==seat)return '当前不能出牌';
    if(action==='pass'){
      if(!g.lead)return '领出时不能选择不要';
      g.plays[seat]=[];g.last={seat,pass:true};g.passes++;
      if(g.passes===g.hands.length-1){g.lead=null;g.passes=0;g.turn=g.lastActor;g.lastActor=null;return}
    }else{
      if(action!=='play'||!Array.isArray(ids)||!ids.length||ids.length>108||new Set(ids).size!==ids.length)return '出牌请求无效';
      const selected=g.hands[seat].filter(c=>ids.includes(c.id));if(selected.length!==ids.length)return '只能打出自己手中的牌';
      const kind=classify(selected,g.mode);if(!beats(kind,g.lead))return '这组牌不合法或压不过上一手';
      g.hands[seat]=g.hands[seat].filter(c=>!ids.includes(c.id));g.plays[seat]=ids;g.played.push(...selected);g.lead=kind;g.lastActor=seat;g.passes=0;g.last={seat,kind};
      if(!g.hands[seat].length){g.winner=seat;g.winners=g.hands.map((_,s)=>s).filter(s=>team(g,s)===team(g,seat));}
    }
    g.turn=(seat+1)%g.hands.length;
  }
  function ai(g,seat,difficulty){
    const hand=g.hands[seat],target=g.lead;
    const known=new Set([...hand,...g.played].map(c=>c.id)),unseen=deck(g.mode).filter(c=>!known.has(c.id));
    const rivals=g.hands.map((h,i)=>team(g,i)!==team(g,seat)?h.length:999),remaining=Math.min(...rivals);
    if(g.mode==='duel')return CardStrategy.choose(hand,target,difficulty,remaining,unseen);
    if(target && team(g,g.lastActor)===team(g,seat) && difficulty!=='easy')return null;
    const picks=options(hand,target,g.mode);
    if(difficulty==='easy')return picks[0]||null;
    const groups=CardRules.groups(hand);let best=null,score=Infinity;
    for(const pick of picks){if(pick.length===hand.length)return pick;const k=classify(pick,g.mode),ids=new Set(pick.map(c=>c.id)),rest=hand.filter(c=>!ids.has(c.id));const splits=CardRules.groups(pick).reduce((s,[v,c])=>{const total=groups.find(([r])=>r===v)[1].length;return s+(c.length<total?(total===4?8:2):0)},0);let cost=CardRules.groups(rest).length*(difficulty==='hard'?4:2)+splits-pick.length+k.main/20;
      if(['bomb','rocket'].includes(k.type)&&remaining>2)cost+=10;
      if(difficulty==='hard'&&classify(rest,g.mode))cost-=8;
      if(remaining<=2&&k.type==='single')cost-=k.main;
      if(cost<score){score=cost;best=pick}}
    return best;
  }
  function settle(state){const g=state.game;if(g.winner===null||state.settled===state.round)return;state.settled=state.round;let points=g.mode==='teams'?1:g.winner===g.landlord?g.hands.length-1:1;
    if(g.mode==='teams'){const side=team(g,g.winner);state.streak=state.streak?.team===side?{team:side,count:state.streak.count+1}:{team:side,count:1};points=state.streak.count}
    state.awards=state.players.map((_,s)=>g.winners.includes(s)?points:0);state.scores=state.scores.map((v,s)=>v+state.awards[s]);
    state.rankedAward=state.kind==='ai'&&state.difficulty==='hard'&&g.winners.includes(0)?(g.mode==='trio'&&g.landlord===0?3:1):0;
  }
  globalThis.MultiGame={modes,classify,beats,options,deck,deal,team,move,ai,settle};
})();

const ROOM_TTL=2*60*60*1000, SESSION_TTL=30*24*60*60*1000;
const randomToken=()=>crypto.randomUUID().replaceAll('-','')+crypto.randomUUID().replaceAll('-','');
const json=(body,status=200,headers={})=>Response.json(body,{status,headers:{'Cache-Control':'no-store',...headers}});
const error=(message,status=400)=>json({error:message},status);
const sha=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))),b=>b.toString(16).padStart(2,'0')).join('');
const safeName=s=>typeof s==='string'&&/^[\p{L}\p{N}_·-]{2,16}$/u.test(s);
async function pinHash(pin,salt,pepper){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin+pepper),'PBKDF2',false,['deriveBits']);return Array.from(new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:100000,hash:'SHA-256'},key,256)),b=>b.toString(16).padStart(2,'0')).join('')}
async function actor(request,db){const token=/\bielts_session=([a-f0-9]{64})\b/.exec(request.headers.get('Cookie')||'')?.[1];if(!token)return null;return db.prepare('SELECT s.actor,s.account_id,s.nickname,a.admin,a.login FROM sessions s LEFT JOIN accounts a ON a.id=s.account_id WHERE s.token_hash=? AND s.expires>?').bind(await sha(token),Date.now()).first()}
async function issue(db,account,nickname){const token=randomToken(),now=Date.now();await db.batch([db.prepare('DELETE FROM sessions WHERE expires<?').bind(now),db.prepare('INSERT INTO sessions VALUES (?,?,?,?,?)').bind(await sha(token),account?.id||randomToken(),account?.id||null,nickname,now+SESSION_TTL)]);return json({ok:true},200,{'Set-Cookie':`ielts_session=${token}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=${SESSION_TTL/1000}`})}
async function limited(db,key,max,windowMs){const now=Date.now();await db.prepare('INSERT INTO auth_limits VALUES (?,1,?) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN until_time<=? THEN 1 ELSE count+1 END, until_time=CASE WHEN until_time<=? THEN excluded.until_time ELSE until_time END').bind(key,now+windowMs,now,now).run();const row=await db.prepare('SELECT count FROM auth_limits WHERE key=?').bind(key).first();return row.count>max}
async function me(db,user){if(!user)return {user:null};let points=0;if(user.account_id)points=(await db.prepare('SELECT COALESCE(SUM(amount),0) AS n FROM points WHERE account_id=?').bind(user.account_id).first()).n;return {user:{nickname:user.nickname,login:user.login||null,guest:!user.account_id,admin:!!user.admin,points}}}
async function auth(request,env,path,body,user){const db=env.DB;
  if(path==='/api/me')return json(await me(db,user));
  if(path==='/api/leaderboard'){const r=await db.prepare('SELECT a.nickname, SUM(p.amount) AS points FROM accounts a JOIN points p ON p.account_id=a.id GROUP BY a.id ORDER BY points DESC,a.created ASC LIMIT 100').bind().all();return json({rows:r.results})}
  if(path==='/api/admin'){if(!user?.admin)return error('仅开发者可访问',403);const stats=await db.prepare('SELECT COUNT(*) AS registered FROM accounts').bind().first();const games=await db.prepare("SELECT COUNT(DISTINCT room || ':' || round) AS scoredGames FROM points").bind().first();return json({...stats,...games})}
  if(path==='/api/logout'){const token=/\bielts_session=([a-f0-9]{64})\b/.exec(request.headers.get('Cookie')||'')?.[1];if(token)await db.prepare('DELETE FROM sessions WHERE token_hash=?').bind(await sha(token)).run();return json({ok:true},200,{'Set-Cookie':'ielts_session=; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=0'})}
  const ip=await sha((request.headers.get('CF-Connecting-IP')||'local')+(env.PIN_PEPPER||''));
  if(path==='/api/guest'){if(await limited(db,'guest:'+ip,30,3600000))return error('创建过于频繁，请稍后再试',429);if(!safeName(body.nickname))return error('昵称需为 2–16 个汉字、字母、数字或下划线');return issue(db,null,body.nickname)}
  if(path==='/api/nickname'){if(!user)return error('请先登录',401);if(!safeName(body.nickname))return error('昵称需为 2–16 个汉字、字母、数字或下划线');await db.batch([...(user.account_id?[db.prepare('UPDATE accounts SET nickname=? WHERE id=?').bind(body.nickname,user.account_id)]:[]),db.prepare('UPDATE sessions SET nickname=? WHERE actor=?').bind(body.nickname,user.actor)]);return json({ok:true})}
  if(!['/api/register','/api/login'].includes(path))return error('接口不存在',404);
  if(!env.PIN_PEPPER)return error('账号服务尚未配置',503);
  if(!safeName(body.login)||!/^\d{4}$/.test(body.pin||''))return error('登录名为 2–16 字，密码必须为四位数字');
  const login=body.login.normalize('NFKC').toLowerCase();if(!safeName(login))return error('登录名格式无效');
  if(await limited(db,'auth-ip:'+ip,40,900000)||await limited(db,'auth-name:'+login,8,900000))return error('尝试次数过多，请 15 分钟后再试',429);
  let account;
  if(path==='/api/register'){
    if(!safeName(body.nickname))return error('请填写 2–16 字昵称');
    if(await limited(db,'register:'+ip,8,3600000))return error('注册过于频繁，请稍后再试',429);
    const admin=login==='甄宝玉';if(admin&&(!env.OWNER_CLAIM_HASH||await sha(String(body.claim||''))!==env.OWNER_CLAIM_HASH))return error('此登录名为开发者保留，请从专属设置入口注册',403);
    if(await db.prepare('SELECT id FROM accounts WHERE login=?').bind(login).first())return error('该登录名已注册',409);
    const salt=randomToken();account={id:randomToken(),login,nickname:body.nickname};try{await db.prepare('INSERT INTO accounts VALUES (?,?,?,?,?,?,?)').bind(account.id,login,body.nickname,salt,await pinHash(body.pin,salt,env.PIN_PEPPER),admin?1:0,Date.now()).run()}catch{return error('该登录名已注册',409)}
  }else{account=await db.prepare('SELECT * FROM accounts WHERE login=?').bind(login).first();const actual=await pinHash(body.pin,account?.salt||'missing-account',env.PIN_PEPPER);if(!account||actual!==account.pin_hash)return error('登录名或密码错误',401)}
  return issue(db,account,account.nickname);
}
function fresh(mode,kind,difficulty,user){const n=MultiGame.modes[mode].n;return {schema:2,mode,kind,difficulty,players:[{id:user.actor,account:user.account_id,name:user.nickname},...Array(n-1).fill(null)],game:null,round:0,scores:Array(n).fill(0),awards:Array(n).fill(0),next:Array(n).fill(false),streak:null}}
function start(state){state.round++;state.game=MultiGame.deal(state.mode);state.next=state.players.map(p=>!!p?.ai);state.game.ready=state.players.map(p=>!!p?.ai);state.awards=state.players.map(()=>0);state.rankedAward=0}
function snapshot(s,seat,version,room){const g=s.game;const common={room,version,mode:s.mode,kind:s.kind,difficulty:s.difficulty,seat,round:s.round,players:s.players.map((p,i)=>p?{name:p.name,ai:!!p.ai,score:s.scores[i],next:s.next[i]}:null),streak:s.streak};if(!g)return {...common,waiting:true};return {...common,waiting:false,hand:g.hands[seat].map(c=>c.id),counts:g.hands.map(h=>h.length),bottom:g.bottom,landlord:g.landlord,turn:g.turn,ready:g.ready,lead:g.lead,lastActor:g.lastActor,plays:g.plays,last:g.last,winner:g.winner,winners:g.winners,awards:s.awards,rankedAward:s.rankedAward}}
function runAI(s){const g=s.game;if(s.kind!=='ai'||!g.ready.every(Boolean))return;let guard=0;while(g.winner===null&&s.players[g.turn].ai&&guard++<4){const cards=MultiGame.ai(g,g.turn,s.difficulty);const problem=MultiGame.move(g,g.turn,cards?'play':'pass',cards?.map(c=>c.id));if(problem)throw new Error('AI illegal move')}MultiGame.settle(s)}
async function persist(db,id,row,s){s.commit=randomToken();const now=Date.now();const statements=[db.prepare('UPDATE rooms SET state=?, version=version+1, expires=?, queue=? WHERE id=? AND version=?').bind(JSON.stringify(s),now+ROOM_TTL,s.queue&&!s.game?1:0,id,row.version)];if(s.rankedAward&&s.players[0].account)statements.push(db.prepare('INSERT OR IGNORE INTO points SELECT ?,?,?,?,? WHERE EXISTS (SELECT 1 FROM rooms WHERE id=? AND json_extract(state,\'$.commit\')=?)').bind(id,s.round,s.players[0].account,s.rankedAward,now,id,s.commit));const result=await db.batch(statements);return !!result[0].meta.changes}
async function roomRequest(db,path,body,user){
  if(!user)return error('请先选择登录或游客进入',401);
  const match=/^\/api\/rooms(?:\/([a-f0-9]{64}))?$/.exec(path);if(!match)return error('房间不存在',404);
  const now=Date.now();let id=match[1];
  if(!id){
    const mode=body.mode||'duel',kind=body.kind||'room',difficulty=body.difficulty||'normal';if(!MultiGame.modes[mode]||!['room','ai'].includes(kind)||!['easy','normal','hard'].includes(difficulty)||kind==='ai'&&!['duel','trio'].includes(mode))return error('不支持的模式');
    if(body.action==='match'&&kind!=='room')return error('匹配只支持真人房间');
    if(!['create','match'].includes(body.action))return error('请求无效');
    if(await limited(db,'rooms:'+user.actor,40,3600000))return error('开局过于频繁，请稍后再试',429);
    await db.prepare('DELETE FROM rooms WHERE expires<?').bind(now).run();
    if(body.action==='match'){
      const list=await db.prepare('SELECT id,version,state FROM rooms WHERE mode=? AND queue=1 AND expires>? LIMIT 20').bind(mode,now).all();
      for(const row of list.results){const s=JSON.parse(row.state);let seat=s.players.findIndex(p=>p?.id===user.actor);if(seat>=0)return json(snapshot(s,seat,row.version,row.id));seat=s.players.indexOf(null);if(seat<0)continue;s.players[seat]={id:user.actor,account:user.account_id,name:user.nickname};if(s.players.every(Boolean))start(s);if(await persist(db,row.id,row,s))return json(snapshot(s,seat,row.version+1,row.id));}
    }
    const s=fresh(mode,kind,difficulty,user);s.queue=body.action==='match';if(kind==='ai'){for(let i=1;i<s.players.length;i++)s.players[i]={id:'ai'+i,name:'电脑 '+i,ai:true};start(s)}
    id=randomToken();await db.prepare('INSERT INTO rooms (id,version,expires,state,mode,queue) VALUES (?,0,?,?,?,?)').bind(id,now+ROOM_TTL,JSON.stringify(s),mode,s.queue?1:0).run();return json(snapshot(s,0,0,id));
  }
  const row=await db.prepare('SELECT version,state,expires FROM rooms WHERE id=? AND expires>?').bind(id,now).first();if(!row)return error('房间已过期或不存在',404);const s=JSON.parse(row.state);if(s.schema!==2)return error('旧版房间已结束，请重新创建',409);let seat=s.players.findIndex(p=>p?.id===user.actor);
  if(body.action==='join'&&seat<0){if(s.kind==='ai')return error('不能加入电脑对局',403);seat=s.players.indexOf(null);if(seat<0||s.game)return error('房间已满或已开始',409);s.players[seat]={id:user.actor,account:user.account_id,name:user.nickname};if(s.players.every(Boolean))start(s)}else{
    if(seat<0)return error('你不在这个房间',403);
    if(['state','join'].includes(body.action)){if(row.expires<now+ROOM_TTL/2)await db.prepare('UPDATE rooms SET expires=? WHERE id=?').bind(now+ROOM_TTL,id).run();return json(snapshot(s,seat,row.version,id))}
    if(body.action==='leave'&&!s.game){s.players[seat]=null;if(!s.players.some(Boolean)){await db.prepare('DELETE FROM rooms WHERE id=? AND version=?').bind(id,row.version).run();return json({left:true})}}
    else{
      if(body.version!==row.version)return error('牌局已更新，请重试',409);if(!s.game)return error('等待其他玩家加入',409);
      if(body.action==='rematch'){if(s.game.winner===null)return error('当前牌局尚未结束',422);s.next[seat]=true;if(s.next.every(Boolean))start(s)}
      else{const problem=MultiGame.move(s.game,seat,body.action,body.ids);if(problem)return error(problem,422);runAI(s);MultiGame.settle(s)}
    }
  }
  if(!await persist(db,id,row,s))return error('牌局已更新，请重试',409);return json(snapshot(s,seat,row.version+1,id));
}
function serveAsset(request, pathname) {
  if (request.method !== 'GET' && request.method !== 'HEAD') return error('请求无效', 405);
  const path = pathname === '/' ? '/index.html' : pathname;
  if (!Object.hasOwn(assets, path)) return error('页面不存在', 404);
  const [type, encoded] = assets[path];
  return new Response(request.method === 'HEAD' ? null : Uint8Array.from(atob(encoded), c => c.charCodeAt(0)), {
    headers: {'Content-Type': type, 'Cache-Control': path.startsWith('/cards/') ? 'public, max-age=86400' : 'no-cache'},
  });
}

export default {async fetch(request,env){const path=new URL(request.url).pathname;if(!path.startsWith('/api/'))return serveAsset(request,path);try{
  if(request.method!=='POST')return error('请求方法无效',405);
  const origin=request.headers.get('Origin');if(origin&&origin!==new URL(request.url).origin)return error('请求来源无效',403);
  let raw='',size=0;const reader=request.body?.getReader();if(!reader)return error('请求无效');const decoder=new TextDecoder();for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>16384){await reader.cancel();return error('请求过大',413)}raw+=decoder.decode(value,{stream:true})}let body;try{body=JSON.parse(raw+decoder.decode())}catch{return error('请求无效')};if(!body||typeof body!=='object')return error('请求无效');
  const user=await actor(request,env.DB);return path.startsWith('/api/rooms')?await roomRequest(env.DB,path,body,user):await auth(request,env,path,body,user);
}catch(err){console.error('Game service failure',err.name);return error('服务暂时不可用，请稍后重试',503)}}};

